upd as (
  update public.questions q set text_he = f.q, explanation_he = f.expl, status = 'active',
         image = jsonb_build_object('kind','photo','url','https://pajqbqjjadwcbpajkiph.supabase.co/storage/v1/object/public/qart/q/' || f.id || '.jpg','credit','איור AI · טריוויה - האלוף','license','AI','fit','contain','w',800,'h',600),
         source_urls = coalesce((select array_agg(u) from unnest(q.source_urls) u where u not like '%commons.wikimedia.org%'),
                                array['https://he.wikipedia.org/wiki/' || replace(f.a0, ' ', '_')]),
         generator = 'illustrated-2026.10.30', verified_by = 'editorial', updated_at = now()
    from f where q.id = f.id
  returning q.id)
update public.question_answers a set text_he = p.txt, is_correct = (p.k = 0)
  from (select f.id, (t.k0 - 1)::int as k, t.txt, (row_number() over (partition by f.id order by md5(f.id || t.k0::text)) - 1)::int as pos
          from f cross join lateral unnest(array[f.a0, f.a1, f.a2, f.a3]) with ordinality t(txt, k0)
         where f.id in (select id from upd)) p
 where a.question_id = p.id and a.position = p.pos;

