('q_deac195405085738','culture','מה רואים בתמונה?','פסיפס','רקמה','קליגרפיה','אוריגמי','פסיפס מרכיבים מאבנים קטנות וצבעוניות, ובישראל נמצאו הרבה רצפות פסיפס עתיקות.'),
('q_203b762608289f29','culture','מה רואים בתמונה?','ויטראז''','רקמה','אוריגמי','קדרות','ויטראז'' עשוי מחתיכות זכוכית צבעוניות, וכשהשמש עוברת דרכו נוצר אור צבעוני.'),
('q_a77d5101f4d7c9f5','culture','איזה חפץ רואים בתמונה?','כיפה','תרבוש','סומבררו','קסדה','כיפה סרוגה סורגים מחוטים דקים, ולפעמים מוסיפים לה דוגמה צבעונית בשוליים.'),
('q_9b2c7994a202913b','culture','איזה חפץ רואים בתמונה?','ספינה בבקבוק','אוריגמי','מטריושקה','קדרות','את הספינה בונים מחוץ לבקבוק עם תרנים מקופלים, ומרימים אותם בעזרת חוט אחרי שהיא בפנים.'),
('q_88a11ff5dfb1a30b','space','איזה ירח רואים בתמונה?','ירח מלא','חצי ירח','סהר','ירח חדש','ירח מלא רואים כשכדור הארץ נמצא בין השמש לירח, והוא זורח בערך כשהשמש שוקעת.'),
('q_e4a039e25bae8a6e','space','איזה ירח רואים בתמונה?','חצי ירח','ירח מלא','ירח חדש','ליקוי ירח','חצי ירח רואים בערך שבוע אחרי המולד, כשהשמש מאירה בדיוק חצי מהצד שפונה אלינו.'),
('q_6a3dc95f1bd3c5bd','space','איך נקרא המקום שממנו משגרים טילים לחלל?','כן שיגור','מצפה כוכבים','שדה תעופה','נמל','ליד כן השיגור יש מגדל גבוה, ודרכו עולים האסטרונאוטים לחללית שבראש הטיל.'),
('q_793a3797baf00a48','space','איזו חליפה רואים בתמונה?','חליפת חלל','חליפת צלילה','חליפת כבאי','חליפת מירוץ','חליפת החלל נותנת לאסטרונאוט אוויר לנשימה ומגינה עליו מקור ומחום קיצוניים.'),
('q_2dc00b7c8c24f6b2','space','מה המקצוע של האדם שבתמונה?','אסטרונאוט','צוללן','כבאי','טייס','האסטרונאוט הישראלי הראשון היה אילן רמון, שטס לחלל בשנת 2003.'),
('q_36abfadc86915ba3','space','איזו קסדה רואים בתמונה?','קסדת אסטרונאוט','קסדת אופניים','קסדת כבאי','קסדת בנייה','בקסדת האסטרונאוט יש מגן מצופה בשכבה דקה של זהב, שמגינה על העיניים מאור השמש החזק.'),
('q_27cc6ecd4aa3c4cb','space','איזו תופעת טבע רואים בתמונה?','מטר מטאורים','זוהר קוטבי','קשת בענן','ליקוי חמה','מטר מטאורים קורה כשכדור הארץ עובר דרך אבק ששביט השאיר אחריו, והגרגירים נשרפים באוויר.')),
n as (select * from n0
       where exists (select 1 from public.questions where id = 'q_1245f0b37962be20')
         and not exists (select 1 from public.questions q where q.id = n0.id)
         and not exists (select 1 from public.questions q join public.question_answers a on a.question_id = q.id and a.is_correct
                          where q.status = 'active' and q.world = n0.world and a.text_he = n0.a0 and q.image is not null)),
ins as (
  insert into public.questions (id, category, topic, difficulty, text_he, explanation_he, template, source_urls,
                                verified_by, generator, obscurity, world, status, image)
  select n.id, n.world, 'illustrated', 'easy', n.q, n.expl, 'illustrated_photo:' || n.world,
         array['https://he.wikipedia.org/wiki/' || replace(n.a0, ' ', '_')],
         'editorial', 'illustrated-2026.10.30', 0.12, n.world, 'active', jsonb_build_object('kind','photo','url','https://pajqbqjjadwcbpajkiph.supabase.co/storage/v1/object/public/qart/q/' || n.id || '.jpg','credit','איור AI · טריוויה - האלוף','license','AI','fit','contain','w',800,'h',600)
    from n
  returning id)
insert into public.question_answers (question_id, position, text_he, is_correct)
select n.id, (row_number() over (partition by n.id order by md5(n.id || t.k0::text)) - 1)::int, t.txt, t.k0 = 1
  from n cross join lateral unnest(array[n.a0, n.a1, n.a2, n.a3]) with ordinality t(txt, k0)
 where n.id in (select id from ins);

select public.refresh_question_ranks();
